1	/**
2	 * 交易系统 — 买卖商品、价格波动、批发进货
3	 *
4	 * 提供: buyGood(), sellGood(), buyWholesale(), updatePrices()
5	 */
6	
7	/** 玩家购买商品 */
8	function buyGood(goodId, qty) {
9	  const state = StateManager.getState();
10	  const good = getGoodById(goodId);
11	  if (!good) {
12	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
13	    return false;
14	  }
15	
16	  const locKey = state.trade.currentLocation;
17	  const price = getCurrentPrice(locKey, goodId);
18	
19	  const totalCost = Math.round(price * qty * 100) / 100;
20	
21	  // 检查现金
22	  if (state.resources.cash < totalCost) {
23	    StateManager.addMessage(
24	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}，你只有 ¥${state.resources.cash}。`,
25	      "danger",
26	    );
27	    return false;
28	  }
29	
30	  // 检查背包容量
31	  const currentItems = state.inventory.items.reduce(
32	    (sum, item) => sum + item.qty,
33	    0,
34	  );
35	  if (currentItems + qty > state.inventory.capacity) {
36	    StateManager.addMessage(
37	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
38	      "danger",
39	    );
40	    return false;
41	  }
42	
43	  // 扣钱
44	  state.resources.cash -= totalCost;
45	
46	  // 加入背包
47	  const existing = state.inventory.items.find((i) => i.id === goodId);
48	  if (existing) {
49	    existing.qty += qty;
50	  } else {
51	    state.inventory.items.push({ id: goodId, qty });
52	  }
53	
54	  StateManager.addMessage(
55	    `🛒 购买了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalCost.toFixed(1)}。`,
56	    "success",
57	  );
58	  return true;
59	}
60	
61	/** 玩家卖出商品 */
62	function sellGood(goodId, qty) {
63	  const state = StateManager.getState();
64	  const good = getGoodById(goodId);
65	  if (!good) {
66	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
67	    return false;
68	  }
69	
70	  // 检查背包
71	  const existing = state.inventory.items.find((i) => i.id === goodId);
72	  if (!existing || existing.qty < qty) {
73	    StateManager.addMessage(`⚠️ 背包中没有足够的${good.name}！`, "danger");
74	    return false;
75	  }
76	
77	  const locKey = state.trade.currentLocation;
78	  const price = getCurrentPrice(locKey, goodId);
79	
80	  const totalEarned = Math.round(price * qty * 100) / 100;
81	
82	  // 加钱
83	  state.resources.cash += totalEarned;
84	  state.resources.totalEarned += totalEarned;
85	
86	  // 从背包移除
87	  existing.qty -= qty;
88	  if (existing.qty <= 0) {
89	    state.inventory.items = state.inventory.items.filter(
90	      (i) => i.id !== goodId,
91	    );
92	  }
93	
94	  // 低买高卖时显示利润
95	  const buyPrice = getAvgBuyPrice(state, goodId); // 估算买入价
96	  let profitMsg = "";
97	  if (buyPrice > 0) {
98	    const profit = totalEarned - buyPrice * qty;
99	    if (profit > 0) {
100	      profitMsg = ` 📈 获利 ¥${profit.toFixed(1)}！`;
101	    } else if (profit < 0) {
102	      profitMsg = ` 📉 亏损 ¥${Math.abs(profit).toFixed(1)}。`;
103	    }
104	  }
105	
106	  StateManager.addMessage(
107	    `💰 卖出了 ${qty}${good.unit}${good.name}，单价 ¥${price.toFixed(1)}，共 ¥${totalEarned.toFixed(1)}。${profitMsg}`,
108	    "success",
109	  );
110	  return true;
111	}
112	
113	/** 批发进货（批发市场专属） */
114	function buyWholesale(goodId, qty) {
115	  const state = StateManager.getState();
116	  const good = getGoodById(goodId);
117	  if (!good) {
118	    StateManager.addMessage("⚠️ 不存在的商品。", "danger");
119	    return false;
120	  }
121	
122	  const locKey = state.trade.currentLocation;
123	  const price = getCurrentPrice(locKey, goodId);
124	
125	  // 批发折扣：批发市场的价格 × 0.7（批量价）
126	  const wholesalePrice = Math.round(price * 0.7 * 100) / 100;
127	  const totalCost = Math.round(wholesalePrice * qty * 100) / 100;
128	
129	  // 最低起批量
130	  if (qty < 5) {
131	    StateManager.addMessage("⚠️ 批发最少购买5件。", "warning");
132	    return false;
133	  }
134	
135	  // 检查现金
136	  if (state.resources.cash < totalCost) {
137	    StateManager.addMessage(
138	      `⚠️ 钱不够！需要 ¥${totalCost.toFixed(1)}。`,
139	      "danger",
140	    );
141	    return false;
142	  }
143	
144	  // 检查背包
145	  const currentItems = state.inventory.items.reduce(
146	    (sum, item) => sum + item.qty,
147	    0,
148	  );
149	  if (currentItems + qty > state.inventory.capacity) {
150	    StateManager.addMessage(
151	      `⚠️ 背包空间不足！（${currentItems}/${state.inventory.capacity}）`,
152	      "danger",
153	    );
154	    return false;
155	  }
156	
157	  // 扣钱
158	  state.resources.cash -= totalCost;
159	
160	  // 记录买入价（用于后续利润计算）
161	  const existing = state.inventory.items.find((i) => i.id === goodId);
162	  if (existing) {
163	    // 加权平均买入价
164	    const oldTotal = (existing.avgBuyPrice || wholesalePrice) * existing.qty;
165	    const newTotal = wholesalePrice * qty;
166	    existing.qty += qty;
167	    existing.avgBuyPrice =
168	      Math.round(((oldTotal + newTotal) / existing.qty) * 100) / 100;
169	  } else {
170	    state.inventory.items.push({
171	      id: goodId,
172	      qty,
173	      avgBuyPrice: wholesalePrice,
174	    });
175	  }
176	
177	  StateManager.addMessage(
178	    `📦 批发进货 ${qty}${good.unit}${good.name}，批发价 ¥${wholesalePrice.toFixed(1)}/件，共 ¥${totalCost.toFixed(1)}。`,
179	    "success",
180	  );
181	  return true;
182	}
183	
184	/** 快速出售（从背包里选一个商品卖） */
185	function quickSell(goodId) {
186	  const state = StateManager.getState();
187	  const existing = state.inventory.items.find((i) => i.id === goodId);
188	  if (!existing || existing.qty <= 0) {
189	    StateManager.addMessage(`⚠️ 背包中没有该商品。`, "warning");
190	    return false;
191	  }
192	  const qty = Math.min(existing.qty, 1); // 默认卖1个
193	  return sellGood(goodId, qty);
194	}
195	
196	/** 获取当前地点某商品的零售价 */
197	function getCurrentPrice(locKey, goodId) {
198	  const state = StateManager.getState();
199	  const prices = state.trade.goodsPrices[locKey];
200	  if (prices && prices[goodId] !== undefined) {
201	    return prices[goodId];
202	  }
203	  const good = getGoodById(goodId);
204	  return good ? good.basePrice : 1;
205	}
206	
207	/** 获取某商品在所有地点的最低价格（用于价格对比） */
208	function getLowestPrice(goodId) {
209	  const state = StateManager.getState();
210	  let lowest = Infinity;
211	  let lowestLoc = null;
212	  for (const locKey of Object.keys(LOCATIONS)) {
213	    const prices = state.trade.goodsPrices[locKey] || {};
214	    const price = prices[goodId];
215	    if (price && price < lowest) {
216	      lowest = price;
217	      lowestLoc = locKey;
218	    }
219	  }
220	  return { price: lowest, location: lowestLoc };
221	}
222	
223	/** 获取某商品在所有地点的最高价格 */
224	function getHighestPrice(goodId) {
225	  const state = StateManager.getState();
226	  let highest = 0;
227	  let highestLoc = null;
228	  for (const locKey of Object.keys(LOCATIONS)) {
229	    const prices = state.trade.goodsPrices[locKey] || {};
230	    const price = prices[goodId];
231	    if (price && price > highest) {
232	      highest = price;
233	      highestLoc = locKey;
234	    }
235	  }
236	  return { price: highest, location: highestLoc };
237	}
238	
239	/** 估算平均买入价 */
240	function getAvgBuyPrice(state, goodId) {
241	  const item = state.inventory.items.find((i) => i.id === goodId);
242	  return item ? item.avgBuyPrice || 0 : 0;
243	}
244	
245	/** 更新所有地点所有商品的价格（每3天调用一次） */
246	function updateAllPrices(state) {
247	  for (const locKey of Object.keys(LOCATIONS)) {
248	    const loc = LOCATIONS[locKey];
249	    // 确保价格对象存在
250	    if (!state.trade.goodsPrices[locKey]) {
251	      state.trade.goodsPrices[locKey] = {};
252	    }
253	    for (const good of GOODS) {
254	      let price = good.basePrice;
255	
256	      // 1. 地点倍率
257	      if (loc.priceMod && loc.priceMod[good.id]) {
258	        price *= loc.priceMod[good.id];
259	      }
260	
261	      // 2. 随机波动 ±25%
262	      const fluctuation = 0.75 + Math.random() * 0.5;
263	      price *= fluctuation;
264	
265	      // 3. 均值回归（10%向旧价格靠拢）
266	      const oldPrice = state.trade.goodsPrices[locKey][good.id] || price;
267	      price = price + (oldPrice - price) * 0.1;
268	
269	      // 4. 限制在合理范围
270	      price = Math.max(
271	        good.basePrice * 0.25,
272	        Math.min(good.basePrice * 6, price),
273	      );
274	      price = Math.round(price * 100) / 100;
275	
276	      state.trade.goodsPrices[locKey][good.id] = price;
277	    }
278	  }
279	  state.trade.lastPriceUpdate = state.player.day;
280	}
