1	/**
2	 * 主渲染调度器
3	 *
4	 * 管理整个 UI 的渲染。使用脏标记 (dirty flag) 按需更新 DOM。
5	 * 渲染函数命名: render<Section>()
6	 */
7	
8	// 当前激活的 Tab
9	let currentTab = "actions";
10	
11	// ====== 主渲染入口 ======
12	function renderAll() {
13	  const state = StateManager.getState();
14	
15	  renderHeader(state);
16	  renderSidebar(state);
17	  renderTabBar(state);
18	  renderCurrentTab(state);
19	  renderMessageLog(state);
20	
21	  StateManager.cleanAllDirty();
22	}
23	
24	// ====== Header 渲染 ======
25	function renderHeader(state) {
26	  const p = state.player;
27	  const r = state.resources;
28	  const phaseLabel = p.phase === "corporate" ? "🏢 职场" : "🏘️ 街头";
29	
30	  document.getElementById("header-day").textContent = p.day;
31	  document.getElementById("header-age").textContent = p.age;
32	  document.getElementById("header-phase").textContent = phaseLabel;
33	  document.getElementById("header-cash").textContent =
34	    "¥" + r.cash.toLocaleString();
35	}
36	
37	// ====== Sidebar 渲染 ======
38	function renderSidebar(state) {
39	  const p = state.player;
40	
41	  if (p.phase === "street") {
42	    renderStreetStats(state);
43	  } else {
44	    renderCorporateStats(state);
45	  }
46	
47	  renderNeedsBars(state);
48	  renderLocation(state);
49	}
50	
51	function renderStreetStats(state) {
52	  const p = state.player;
53	  setStatBar("stat-physique", p.physique, "physique");
54	  setStatBar("stat-intelligence", p.intelligence, "intelligence");
55	  setStatBar("stat-agility", p.agility, "agility");
56	  setStatBar("stat-mental", p.mental, "mental-bar");
57	}
58	
59	function renderCorporateStats(state) {
60	  const c = state.player.corporate;
61	  // 切换侧边栏区域显示
62	  document.getElementById("street-stats-section").style.display = "none";
63	  document.getElementById("corp-stats-section").style.display = "block";
64	
65	  setStatBar("stat-hair", c.hair, "hair");
66	  setStatBar("stat-dignity", c.dignity, "dignity");
67	  setStatBar("stat-kpi", c.kpi, "kpi");
68	  setStatBar("stat-ability", c.ability, "intelligence");
69	  setStatBar("stat-upward", c.upwardMgmt, "physique");
70	  setStatBar("stat-popularity", c.popularity, "happiness");
71	  setStatBar("stat-risk", c.risk, "risk");
72	}
73	
74	function renderNeedsBars(state) {
75	  const n = state.needs;
76	  const s = state.status;
77	  setStatBar("stat-hunger", n.hunger, "hunger");
78	  setStatBar("stat-fatigue", n.fatigue, "fatigue");
79	  setStatBar("stat-hygiene", n.hygiene, "hygiene");
80	  setStatBar("stat-happiness", n.happiness, "happiness");
81	  setStatBar("stat-health", s.health, "health");
82	  setStatBar("stat-fame", s.fame, "fame");
83	}
84	
85	function renderLocation(state) {
86	  const locKey = state.trade.currentLocation;
87	  const loc = getLocation(locKey);
88	  if (loc) {
89	    document.getElementById("location-name").textContent = loc.name;
90	    document.getElementById("location-desc").textContent = loc.desc;
91	  }
92	
93	  // 服务标签
94	  const servicesEl = document.getElementById("location-services");
95	  if (servicesEl) {
96	    const badges = getLocationServiceBadges(locKey);
97	    servicesEl.innerHTML = badges
98	      .map(
99	        (b) =>
100	          `<span style="font-size:10px;padding:2px 6px;border-radius:3px;background:${b.bg};color:${b.color};border:1px solid ${b.color};">${b.icon} ${b.label}</span>`,
101	      )
102	      .join("");
103	  }
104	
105	  // 附近可前往地点（仅街头阶段显示）
106	  const nearbySection = document.getElementById("nearby-section");
107	  if (nearbySection) {
108	    nearbySection.style.display = state.player.phase === "street" ? "" : "none";
109	  }
110	  const nearbyEl = document.getElementById("nearby-locations");
111	  if (nearbyEl && state.player.phase === "street") {
112	    const reachable = getReachableLocations(locKey);
113	    if (reachable.length > 0) {
114	      nearbyEl.innerHTML = reachable
115	        .map((destKey) => {
116	          const dest = getLocation(destKey);
117	          if (!dest) return "";
118	          const badges = getLocationServiceBadges(destKey);
119	          const badgeStr =
120	            badges.length > 0
121	              ? badges
122	                  .slice(0, 2)
123	                  .map((b) => `${b.icon}`)
124	                  .join(" ")
125	              : "";
126	          return `
127	          <div class="nearby-loc-item" data-dest="${destKey}"
128	               style="padding:6px 8px;background:var(--bg-card);border:1px solid var(--border);border-radius:4px;cursor:pointer;font-size:11px;display:flex;justify-content:space-between;align-items:center;transition:all 0.2s;"
129	               onmouseover="this.style.borderColor='var(--accent)';this.style.background='var(--bg-card-hover)';"
130	               onmouseout="this.style.borderColor='var(--border)';this.style.background='var(--bg-card)';">
131	            <span>🚶 <strong>${dest.name}</strong> <span style="color:var(--text-muted);font-size:10px;">${dest.type === "commercial" ? "商业" : dest.type === "industrial" ? "工业" : dest.type === "residential" ? "居住" : dest.type === "service" ? "服务" : dest.type === "education" ? "教育" : dest.type === "corporate" ? "职场" : dest.type === "recreation" ? "娱乐" : dest.type === "institutional" ? "机构" : ""}</span></span>
132	            <span style="font-size:10px;">${badgeStr}</span>
133	          </div>`;
134	        })
135	        .join("");
136	      // 绑定点击
137	      setTimeout(() => {
138	        nearbyEl.querySelectorAll(".nearby-loc-item").forEach((item) => {
139	          item.addEventListener("click", () => {
140	            StateManager.update("trade.currentLocation", item.dataset.dest);
141	            const dest = getLocation(item.dataset.dest);
142	            StateManager.addMessage(
143	              `🚶 你来到了${dest ? dest.name : item.dataset.dest}。`,
144	              "info",
145	            );
146	            renderAll();
147	          });
148	        });
149	      }, 0);
150	    } else {
151	      nearbyEl.innerHTML =
152	        '<span style="font-size:11px;color:var(--text-muted);">没有可通行路线</span>';
153	    }
154	  }
155	  const HOUSING_NAMES = ["🌃 露宿街头", "🛏️ 合租床位", "🚪 单间", "🏠 一居室"];
156	  const houseName = HOUSING_NAMES[state.housing?.tier || 0] || HOUSING_NAMES[0];
157	  const houseEl = document.getElementById("housing-info");
158	  if (houseEl) {
159	    const totalCap = state.inventory.capacity;
160	    const itemCount = (state.inventory.items || []).reduce(
161	      (s, i) => s + i.qty,
162	      0,
163	    );
164	    const HOUSING_RENTS = [0, 12, 25, 50];
165	    const curRent = HOUSING_RENTS[state.housing?.tier || 0] || 0;
166	    houseEl.innerHTML = `
167	      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
168	        <span style="font-size:12px;">${houseName}</span>
169	        ${curRent > 0 ? `<span style="font-size:10px;color:var(--warning);">日租¥${curRent}</span>` : ""}
170	      </div>
171	      <div style="font-size:11px;color:var(--text-muted);">
172	        🎒 背包 ${itemCount}/${totalCap}
173	        ${state.housing?.storageRented ? " 📦 已租仓库" : ""}
174	      </div>
175	      ${state.housing?.tier < 3 ? `<div style="font-size:10px;color:var(--text-muted);margin-top:3px;">💡 去<strong style="color:var(--accent);">城中村</strong>可升级住所</div>` : ""}
176	    `;
177	  }
178	}
179	
180	/** 获取地点服务标签 */
181	function getLocationServiceBadges(locKey) {
182	  const badges = [];
183	  const loc = getLocation(locKey);
184	  if (!loc) return badges;
185	
186	  // 可租房
187	  if (locKey === "slum") {
188	    badges.push({
189	      icon: "🏠",
190	      label: "租房",
191	      bg: "rgba(46,204,113,0.1)",
192	      color: "#2ecc71",
193	    });
194	  }
195	  // 可租仓库 & 批发
196	  if (locKey === "wholesaleMarket") {
197	    badges.push({
198	      icon: "📦",
199	      label: "仓库+批发",
200	      bg: "rgba(243,156,18,0.1)",
201	      color: "#f39c12",
202	    });
203	  }
204	  // 医院
205	  if (locKey === "hospital") {
206	    badges.push({
207	      icon: "🏥",
208	      label: "看病",
209	      bg: "rgba(231,76,60,0.1)",
210	      color: "#e74c3c",
211	    });
212	  }
213	  // 银行
214	  if (locKey === "bank") {
215	    badges.push({
216	      icon: "🏦",
217	      label: "存取款",
218	      bg: "rgba(52,152,219,0.1)",
219	      color: "#3498db",
220	    });
221	  }
222	  // 培训
223	  if (locKey === "trainingCenter") {
224	    badges.push({
225	      icon: "📚",
226	      label: "学习考证",
227	      bg: "rgba(155,89,182,0.1)",
228	      color: "#9b59b6",
229	    });
230	  }
231	  // 公园
232	  if (locKey === "park") {
233	    badges.push({
234	      icon: "🌳",
235	      label: "放松",
236	      bg: "rgba(46,204,113,0.1)",
237	      color: "#2ecc71",
238	    });
239	  }
240	  // 科技园
241	  if (locKey === "techPark") {
242	    badges.push({
243	      icon: "💼",
244	      label: "应聘",
245	      bg: "rgba(0,180,216,0.1)",
246	      color: "#00b4d8",
247	    });
248	  }
249	  // 商业区
250	  if (locKey === "commercialDist") {
251	    badges.push({
252	      icon: "🛍️",
253	      label: "购物+摆摊",
254	      bg: "rgba(0,180,216,0.1)",
255	      color: "#00b4d8",
256	    });
257	  }
258	  // 工作数量
259	  if (loc.jobs && loc.jobs.length > 0) {
260	    badges.push({
261	      icon: "💼",
262	      label: loc.jobs.length + "种工作",
263	      bg: "rgba(243,156,18,0.1)",
264	      color: "#f39c12",
265	    });
266	  }
267	
268	  return badges;
269	}
270	
271	// ====== Tab Bar ======
272	function renderTabBar(state) {
273	  const tabs = document.querySelectorAll("#tab-bar .tab-btn");
274	  tabs.forEach((btn) => {
275	    btn.classList.toggle("active", btn.dataset.tab === currentTab);
276	
277	    // 某些 Tab 在特定阶段隐藏
278	    if (btn.dataset.tab === "corp" && state.player.phase !== "corporate") {
279	      btn.style.display = "none";
280	    } else if (btn.dataset.tab === "trade" && state.player.phase !== "street") {
281	      btn.style.display = "none";
282	    } else {
283	      btn.style.display = "";
284	    }
285	  });
