169	// ====== 状态管理器 ======
170	class GameStateManager {
171	  constructor() {
172	    this._state = null;
173	    this._dirtyFlags = new Set();
174	    this._listeners = [];
175	  }
176	
177	  /** 初始化新游戏 */
178	  newGame() {
179	    this._state = createDefaultState();
180	    this._markAllDirty();
181	    this._notify();
182	    return this._state;
183	  }
184	
185	  /** 获取当前完整状态（只读引用，请勿直接修改嵌套对象） */
186	  getState() {
187	    if (!this._state) {
188	      throw new Error(
189	        "GameState not initialized. Call newGame() or loadGame() first.",
190	      );
191	    }
192	    return this._state;
193	  }
194	
195	  /** 获取状态某个路径的值 */
196	  get(path) {
197	    const parts = path.split(".");
198	    let val = this.getState();
199	    for (const p of parts) {
200	      if (val == null) return undefined;
201	      val = val[p];
202	    }
203	    return val;
204	  }
205	
206	  /**
207	   * 更新状态某个路径的值
208	   * 用法: update('player.age', 25) 或 update('player', { age: 25, ... })
209	   */
210	  update(path, value) {
211	    const parts = path.split(".");
212	    const state = this.getState();
213	
214	    // 导航到父对象
215	    let parent = state;
216	    for (let i = 0; i < parts.length - 1; i++) {
217	      parent = parent[parts[i]];
218	    }
219	
220	    const key = parts[parts.length - 1];
221	    parent[key] = value;
222	
223	    // 标记脏路径
224	    this._dirtyFlags.add(path);
225	    this._notify();
226	  }
227	
228	  /** 批量更新（用于一次性修改多个字段） */
229	  batchUpdate(updates) {
230	    for (const [path, value] of Object.entries(updates)) {
231	      const parts = path.split(".");
232	      const state = this.getState();
233	      let parent = state;
234	      for (let i = 0; i < parts.length - 1; i++) {
235	        parent = parent[parts[i]];
236	      }
237	      parent[parts[parts.length - 1]] = value;
238	      this._dirtyFlags.add(path);
239	    }
240	    this._notify();
241	  }
242	
243	  /** 添加消息到日志 */
244	  addMessage(text, type = "info") {
245	    const state = this.getState();
246	    state.messageLog.push({
247	      day: state.player.day,
248	      text,
249	      type, // 'info'|'success'|'danger'|'event'|'warning'
250	    });
251	    // 限制日志长度
252	    if (state.messageLog.length > 500) {
253	      state.messageLog = state.messageLog.slice(-300);
254	    }
255	    this._dirtyFlags.add("messageLog");
256	    this._notify();
257	  }
258	
259	  /** 导入存档 */
260	  importState(savedState) {
261	    this._state = savedState;
262	    this._state.lastPlayedAt = Date.now();
263	    this._markAllDirty();
264	    this._notify();
265	  }
266	
267	  /** 检查路径是否脏（自上次 cleanDirty 后） */
268	  isDirty(path) {
269	    return this._dirtyFlags.has(path);
270	  }
271	
272	  /** 清除所有脏标记（渲染后调用） */
273	  cleanAllDirty() {
274	    this._dirtyFlags.clear();
275	  }
276	
277	  /** 订阅状态变更 */
278	  onChange(callback) {
279	    this._listeners.push(callback);
280	  }
281	
282	  // ====== 内部方法 ======
283	  _markAllDirty() {
284	    this._dirtyFlags.add("*");
285	  }
286	
287	  _notify() {
288	    for (const cb of this._listeners) {
289	      try {
290	        cb(this._state);
291	      } catch (e) {
292	        /* 静默 */
293	      }
294	    }
295	  }
296	}
297	
298	// ====== 单例导出 ======
299	const StateManager = new GameStateManager();
300	
301	// 使其在全局可访问（方便调试）
302	if (typeof window !== "undefined") {
303	  window.StateManager = StateManager;
304	}
