1	/**
2	 * 需求系统 — 饥饱/疲劳/卫生/心情衰减 + 情绪状态判定 + 伤病效果
3	 */
4	
5	/** 每日需求衰减 */
6	function applyNeedsDecay(state) {
7	  const n = state.needs;
8	  n.hunger = Math.max(0, n.hunger - 18);
9	  n.hygiene = Math.max(0, n.hygiene - 8);
10	  n.happiness = Math.max(0, n.happiness - 3);
11	  // fatigue 在 endDay 中通过睡眠恢复单独处理
12	}
13	
14	/** 检查需求阈值并施加惩罚 */
15	function checkNeedsThresholds(state) {
16	  const n = state.needs;
17	  const msgs = [];
18	
19	  if (n.hunger < 15) {
20	    state.status.health = Math.max(0, state.status.health - 5);
21	    msgs.push("⚠️ 极度饥饿！健康-5。赶紧吃点什么！");
22	  } else if (n.hunger < 30) {
23	    state.status.health = Math.max(0, state.status.health - 2);
24	    msgs.push("🍞 肚子饿了，工作效率下降。");
25	  }
26	
27	  if (n.hygiene < 15) {
28	    state.status.health = Math.max(0, state.status.health - 3);
29	    msgs.push("🦠 卫生极差！容易生病。去洗个澡吧。");
30	  }
31	
32	  if (n.fatigue > 85) {
33	    state.status.health = Math.max(0, state.status.health - 3);
34	    msgs.push("😵 极度疲劳！需要休息或睡眠。");
35	  }
36	
37	  if (n.happiness < 15) {
38	    msgs.push("😢 心情极度低落，做什么都提不起劲。");
39	  }
40	
41	  for (const msg of msgs) {
42	    StateManager.addMessage(msg, "warning");
43	  }
44	}
45	
46	/** 伤病每日结算 */
47	function tickHealthStatus(state) {
48	  const st = state.status;
49	  if (st.sick) {
50	    st.health = Math.max(0, st.health - 3);
51	    if (Math.random() < 0.12) {
52	      st.sick = false;
53	      StateManager.addMessage("🤒 病好了，身体恢复了。", "info");
54	    }
55	  }
56	  if (st.injured) {
57	    st.health = Math.max(0, st.health - 2);
58	    if (Math.random() < 0.07) {
59	      st.injured = false;
60	      StateManager.addMessage("🩹 伤好了，可以正常干活了。", "info");
61	    }
62	  }
63	  // 自然恢复
64	  if (!st.sick && !st.injured && st.health < 100) {
65	    st.health = Math.min(100, st.health + 1);
66	  }
67	}
68	
69	/** 判定情绪状态 */
70	function determineEmotionalState(state) {
71	  const p = state.player;
72	  const n = state.needs;
73	  let score = 50;
74	
75	  score += (n.happiness - 50) * 0.3;
76	  if (n.fatigue > 80) score -= 20;
77	  else if (n.fatigue > 60) score -= 10;
78	  else if (n.fatigue < 20) score += 5;
79	  if (n.hunger < 20) score -= 15;
80	  else if (n.hunger < 40) score -= 5;
81	  if (n.hygiene < 20) score -= 10;
82	  score += (p.mental - 50) * 0.15;
83	  if (state.status.health < 30) score -= 20;
84	  if (state.status.injured) score -= 10;
85	  if (state.status.sick) score -= 8;
86	
87	  let emotionalState;
88	  if (score < 15) emotionalState = "depressed";
89	  else if (score < 30) emotionalState = "sad";
90	  else if (score < 45) emotionalState = "stressed";
91	  else if (score < 60) emotionalState = "stable";
92	  else if (score < 80) emotionalState = "happy";
93	  else emotionalState = "happy";
94	
95	  state.status.emotionalState = emotionalState;
96	  return emotionalState;
97	}
98	
99	/** 情绪对工作的修正 */
100	function getEmotionWorkModifier(state) {
101	  const emo = state.status.emotionalState || "stable";
102	  const mods = {
103	    depressed: { pay: 0.45, injury: 2.5, skillXp: 0.3 },
104	    sad: { pay: 0.65, injury: 1.5, skillXp: 0.5 },
105	    stressed: { pay: 0.8, injury: 1.3, skillXp: 0.7 },
106	    stable: { pay: 1.0, injury: 1.0, skillXp: 1.0 },
107	    happy: { pay: 1.25, injury: 0.7, skillXp: 1.5 },
108	  };
109	  return mods[emo] || mods.stable;
110	}
111	
112	/** 获取情绪图标 */
113	function getEmotionIcon(state) {
114	  const icons = {
115	    depressed: "😢",
116	    sad: "😔",
117	    stressed: "😰",
118	    stable: "😐",
119	    happy: "😊",
120	  };
121	  return icons[state.status.emotionalState] || "😐";
122	}
