180	/** 初始化各地商品价格 */
181	function initializePrices() {
182	  const state = StateManager.getState();
183	  for (const locKey of Object.keys(LOCATIONS)) {
184	    state.trade.goodsPrices[locKey] = {};
185	    const loc = LOCATIONS[locKey];
186	    for (const good of GOODS) {
187	      let price = good.basePrice;
188	      if (loc.priceMod && loc.priceMod[good.id]) {
189	        price *= loc.priceMod[good.id];
190	      }
191	      // 随机波动 ±10%
192	      price *= 0.9 + Math.random() * 0.2;
193	      price = Math.round(price * 100) / 100;
194	      state.trade.goodsPrices[locKey][good.id] = price;
195	    }
196	  }
197	  state.trade.lastPriceUpdate = state.player.day;
198	}
