963	    skill.level++;
964	    skill.xp -= xpNeeded;
965	    StateManager.addMessage(
966	      `⭐ ${getSkillName(skillKey)}升级到 Lv.${skill.level}！`,
967	      "success",
968	    );
969	  }
970	}
