146	/** 获取随机新闻事件 */
147	function getRandomNewsEvent() {
148	  // 按类型加权：价格40%，工作25%，个人20%，政策15%
149	  const weights = { price: 40, job: 25, personal: 20, policy: 15 };
150	  const total = Object.values(weights).reduce((a, b) => a + b, 0);
151	  let roll = Math.random() * total;
152	
153	  for (const [type, weight] of Object.entries(weights)) {
154	    roll -= weight;
155	    if (roll <= 0) {
156	      const typeEvents = NEWS_EVENTS.filter((e) => e.type === type);
157	      return typeEvents[Math.floor(Math.random() * typeEvents.length)];
158	    }
159	  }
160	  return NEWS_EVENTS[Math.floor(Math.random() * NEWS_EVENTS.length)];
161	}
