163	/** 应用新闻效果 */
164	function applyNewsEffect(news, state) {
165	  const effects = news.effects;
166	
167	  // 价格修正
168	  if (effects.priceMod) {
169	    for (const [goodId, multiplier] of Object.entries(effects.priceMod)) {
170	      for (const locKey of Object.keys(LOCATIONS)) {
171	        const prices = state.trade.goodsPrices[locKey];
172	        if (prices && prices[goodId]) {
173	          prices[goodId] = Math.round(prices[goodId] * multiplier * 100) / 100;
174	        }
175	      }
176	    }
177	  }
178	
179	  // 工作奖励/惩罚
180	  if (effects.jobBonus) {
181	    for (const jobId of effects.jobBonus) {
182	      state._jobMultipliers = state._jobMultipliers || {};
183	      state._jobMultipliers[jobId] =
184	        (state._jobMultipliers[jobId] || 1) * effects.jobMultiplier;
185	    }
186	  }
187	  if (effects.jobPenalty) {
188	    for (const jobId of effects.jobPenalty) {
189	      state._jobMultipliers = state._jobMultipliers || {};
190	      state._jobMultipliers[jobId] =
191	        (state._jobMultipliers[jobId] || 1) * effects.jobMultiplier;
192	    }
193	  }
194	  if (effects.allJobsBonus) {
195	    state._allJobsBonus = (state._allJobsBonus || 1) * effects.allJobsBonus;
196	  }
197	
198	  // 现金
199	  if (effects.cashBonus) {
200	    state.resources.cash += effects.cashBonus;
201	    state.resources.totalEarned += effects.cashBonus;
202	  }
203	  if (effects.cashLoss) {
204	    state.resources.cash = Math.max(0, state.resources.cash - effects.cashLoss);
205	  }
206	
207	  // 需求
208	  if (effects.hungerBonus)
209	    state.needs.hunger = Math.min(
210	      100,
211	      state.needs.hunger + effects.hungerBonus,
212	    );
213	  if (effects.fatigueBonus)
214	    state.needs.fatigue = Math.max(
215	      0,
216	      state.needs.fatigue - effects.fatigueBonus,
217	    );
218	  if (effects.fatiguePenalty)
219	    state.needs.fatigue = Math.min(
220	      100,
221	      state.needs.fatigue + effects.fatiguePenalty,
222	    );
223	  if (effects.happinessBonus)
224	    state.needs.happiness = Math.min(
225	      100,
226	      state.needs.happiness + effects.happinessBonus,
227	    );
228	
229	  // 技能经验
230	  if (effects.skillXp) {
231	    const skillKeys = Object.keys(state.skills);
232	    const key = skillKeys[Math.floor(Math.random() * skillKeys.length)];
233	    state.skills[key].xp += effects.skillXp;
234	  }
235	
236	  return effects;
237	}
