239	/** 清除过期新闻效果 */
240	function cleanupExpiredNews(state) {
241	  state.activeNews = (state.activeNews || []).filter((news) => {
242	    if (news._appliedDay === undefined) news._appliedDay = state.player.day;
243	    return state.player.day - news._appliedDay < (news.effects.duration || 5);
244	  });
245	
246	  // 恢复工作倍率
247	  if (state.activeNews.length === 0) {
248	    state._jobMultipliers = {};
249	    state._allJobsBonus = 1;
250	  }
251	}
